<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
const localToday=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};const props=defineProps<{activeTab:string}>();const month=ref(localToday().slice(0,7));const modal=ref('');const loading=ref(true);const error=ref('');const collectionTab=ref<'saving'|'debt'>('saving');const settingsTab=ref<'goal'|'card'|'category'|'breakdown'>('goal');
const dashboard=ref<any>({goalAmount:50000000,goalYears:3,goalStartDate:'',monthlyBudget:700000,totalSaving:0,expense:0,saving:0,breakdown:[]});const breakdownMonth=ref(localToday().slice(0,7));const breakdownData=ref<any[]>([]);const entries=ref<any[]>([]);const categories=ref<any[]>([]);const savings=ref<any[]>([]);const debts=ref<any[]>([]);const cards=ref<any[]>([]);const goal=ref({amount:'50000000',years:'3',startDate:localToday()});const budget=ref<any>({amount:'700000',copyNext:false});
const entry=ref<any>({date:localToday(),type:'EXPENSE',categoryGroup:'',categoryId:'',amount:'',memo:'',cardId:'',savingsProductId:''});const quickRows=ref<any[]>([{amount:'',categoryGroup:'',categoryId:''}]);const card=ref({name:'',type:'체크카드',isDefault:true});const savingForm=ref<any>({name:'',type:'적금',rate:'0',maturityDate:'',amount:'0'});const debtForm=ref<any>({id:null,name:'',balance:'',rate:'0',dueDate:''});const payment=ref<any>({debtId:'',amount:''});const category=ref<any>({id:null,name:'',type:'EXPENSE',detail:'',emoji:'🌱',color:'#7DBA8B'});
const won=(v:any)=>`${Number(v||0).toLocaleString('ko-KR')}원`;const man=(v:any)=>`(${Math.round(Number(v||0)/10000).toLocaleString('ko-KR')}만원)`;const monthLabel=computed(()=>month.value.replace('-','년 ')+'월');const percent=computed(()=>Math.min(100,Math.round(dashboard.value.totalSaving/Math.max(1,dashboard.value.goalAmount)*100)));const budgetPercent=computed(()=>Math.min(100,Math.round(Number(dashboard.value.expense||0)/Math.max(1,Number(dashboard.value.monthlyBudget||1))*100)));const defaultCard=computed(()=>cards.value.find(c=>c.is_default));const incomeCats=computed(()=>categories.value.filter(c=>c.category_type==='INCOME'));const expenseCats=computed(()=>categories.value.filter(c=>c.category_type==='EXPENSE'));const entryGroups=computed(()=>[...new Set((entry.value.type==='INCOME'?incomeCats.value:expenseCats.value).map(c=>c.name))]);const entryDetails=computed(()=>(entry.value.type==='INCOME'?incomeCats.value:expenseCats.value).filter(c=>!entry.value.categoryGroup||c.name===entry.value.categoryGroup));const quickGroups=computed(()=>[...new Set(expenseCats.value.map(c=>c.name))]);const quickDetails=(r:any)=>expenseCats.value.filter(c=>!r.categoryGroup||c.name===r.categoryGroup);const groupedSavings=computed(()=>{const m=new Map<string,any>();for(const s of savings.value){const o=m.get(s.name);if(o)o.current_amount+=Number(s.current_amount||0);else m.set(s.name,{...s,current_amount:Number(s.current_amount||0)})}return[...m.values()]});const breakdownTotal=computed(()=>breakdownData.value?.reduce((n:number,x:any)=>n+Number(x.amount||0),0)||0);const breakdownColor=(x:any,i:number)=>x.entry_type==='DEBT_REPAYMENT'?'#4b91c2':x.entry_type==='SAVING'?'#7c65c5':['#e7798d','#ef9bb0','#d86b82','#f2b3c0','#c95b72'][i%5];const breakdownLabel=(x:any)=>x.entry_type==='DEBT_REPAYMENT'?'빚 상환':x.detail_name;const pieStyle=computed(()=>{let p=0;const stops=(breakdownData.value||[]).map((x:any,i:number)=>{const s=p;p+=Number(x.amount||0)/Math.max(1,breakdownTotal.value)*100;return`${breakdownColor(x,i)} ${s}% ${p}%`});return{background:`conic-gradient(${stops.join(',')||'#e6efe5 0 100%'}`}});const calendar=computed<any[]>(()=>{const[y=0,m=1]=month.value.split('-').map(Number);const max=new Date(y,m,0).getDate();const pad=(new Date(y,m-1,1).getDay()+6)%7;return[...Array.from({length:pad},(_,i)=>({blank:true,key:`b${i}`})),...Array.from({length:max},(_,i)=>{const date=`${month.value}-${String(i+1).padStart(2,'0')}`;return{date,day:i+1,blank:false,items:entries.value.filter(e=>e.entry_date?.slice(0,10)===date)}})]});
async function api(path:string,options?:RequestInit){const r=await fetch(`/api${path}`,{headers:{'Content-Type':'application/json'},...options});if(!r.ok)throw Error(await r.text());return r.json()}async function load(){loading.value=true;try{[dashboard.value,entries.value,categories.value,savings.value,debts.value,cards.value,budget.value,breakdownData.value]=await Promise.all([api('/dashboard'),api(`/entries?month=${month.value}`),api('/categories'),api('/savings-products'),api('/debts'),api('/cards'),api(`/budgets?month=${month.value}`),api(`/breakdown?month=${month.value}`)]);breakdownMonth.value=month.value;goal.value={amount:String(dashboard.value.goalAmount),years:String(dashboard.value.goalYears||3),startDate:dashboard.value.goalStartDate?.slice(0,10)||goal.value.startDate};budget.value.amount=String(budget.value.amount||dashboard.value.monthlyBudget);entry.value.cardId=defaultCard.value?.id||''}catch{error.value='서버와 연결할 수 없어요.'}finally{loading.value=false}}watch(month,load);onMounted(load)
async function saveGoal(){await api('/settings',{method:'PUT',body:JSON.stringify({goalAmount:Number(goal.value.amount),goalYears:Number(goal.value.years),goalStartDate:goal.value.startDate,cardPaymentDay:dashboard.value.cardPaymentDay})});modal.value='';await load()}async function saveBudget(){await api('/budgets',{method:'PUT',body:JSON.stringify({month:month.value,amount:Number(budget.value.amount),copyNext:budget.value.copyNext})});modal.value='';await load()}async function saveEntry(){const c=categories.value.find(x=>x.id===Number(entry.value.categoryId));const saving=entry.value.type==='SAVING';const repayment=entry.value.type==='DEBT_REPAYMENT';const debt=debts.value.find(x=>x.id===Number(entry.value.debtId));const body={date:entry.value.date,type:entry.value.type,categoryId:(saving||repayment)?null:Number(entry.value.categoryId),category:saving?'저축':repayment?'빚 상환':c?.name,detail:saving?savings.value.find(s=>s.id===Number(entry.value.savingsProductId))?.name:repayment?debt?.name:c?.detail_name,amount:Number(entry.value.amount),memo:entry.value.memo,cardId:entry.value.cardId?Number(entry.value.cardId):defaultCard.value?.id,savingsProductId:saving?Number(entry.value.savingsProductId):null,debtId:repayment?Number(entry.value.debtId):null};await api(entry.value.id?`/entries/${entry.value.id}`:'/entries',{method:entry.value.id?'PUT':'POST',body:JSON.stringify(body)});modal.value='';await load()}async function saveQuick(){for(const r of quickRows.value.filter(x=>x.amount&&x.categoryId)){const c=categories.value.find(x=>x.id===Number(r.categoryId));await api('/entries',{method:'POST',body:JSON.stringify({date:entry.value.date,type:'EXPENSE',categoryId:Number(r.categoryId),category:c?.name,detail:c?.detail_name,amount:Number(r.amount),cardId:defaultCard.value?.id})})}modal.value='';await load()}async function saveSaving(){const method=savingForm.value.id?'PUT':'POST';await api(savingForm.value.id?`/savings-products/${savingForm.value.id}`:'/savings-products',{method,body:JSON.stringify({...savingForm.value,rate:Number(savingForm.value.rate),amount:Number(savingForm.value.amount)})});modal.value='';await load()}async function deleteSaving(id:number){if(confirm('이 저축상품을 삭제할까요?')){await api(`/savings-products/${id}`,{method:'DELETE'});await load()}}async function saveDebt(){const method=debtForm.value.id?'PUT':'POST';await api(debtForm.value.id?`/debts/${debtForm.value.id}`:'/debts',{method,body:JSON.stringify({...debtForm.value,balance:Number(debtForm.value.balance),rate:Number(debtForm.value.rate)})});modal.value='';await load()}async function deleteDebt(id:number){if(confirm('이 빚을 삭제할까요?')){await api(`/debts/${id}`,{method:'DELETE'});await load()}}async function savePayment(){await api(`/debts/${payment.value.debtId}/payments`,{method:'POST',body:JSON.stringify({month:month.value,amount:Number(payment.value.amount)})});modal.value='';await load()}async function addCard(){await api('/cards',{method:'POST',body:JSON.stringify(card.value)});modal.value='';await load()}async function setDefault(id:number){await api(`/cards/${id}/default`,{method:'PUT'});await load()}async function saveCategory(){const method=category.value.id?'PUT':'POST';await api(category.value.id?`/categories/${category.value.id}`:'/categories',{method,body:JSON.stringify(category.value)});modal.value='';await load()}async function deleteCategory(id:number){if(confirm('이 카테고리를 삭제할까요?')){await api(`/categories/${id}`,{method:'DELETE'});await load()}}async function deleteEntry(id:number){if(confirm('이 거래를 삭제할까요?')){await api(`/entries/${id}`,{method:'DELETE'});await load()}}function editEntry(e:any){entry.value={id:e.id,date:e.entry_date?.slice(0,10),type:e.entry_type,categoryGroup:e.category_name,categoryId:e.category_id||'',amount:String(e.amount),memo:e.memo||'',cardId:e.card_id||'',savingsProductId:e.savings_product_id||'',debtId:e.debt_id||''};modal.value='entry'}function openEntry(date=localToday()){entry.value={...entry.value,date,type:'EXPENSE',categoryGroup:'',categoryId:'',debtId:'',cardId:defaultCard.value?.id||''};modal.value='entry'}function openQuick(date=localToday()){entry.value.date=date;quickRows.value=[{amount:'',categoryGroup:'',categoryId:''}];modal.value='quick'}function editSaving(s:any){savingForm.value={...s,rate:String(s.interest_rate),amount:String(s.current_amount)};modal.value='saving'}function editDebt(d:any){debtForm.value={id:d.id,name:d.name,balance:d.balance,rate:d.interest_rate,dueDate:d.due_date?.slice(0,10)||''};modal.value='debt'}function editCategory(c:any){category.value={id:c.id,name:c.name,type:c.category_type,detail:c.detail_name||'',emoji:c.emoji||'🌱',color:c.color||'#7DBA8B'};modal.value='category'}function shiftBreakdown(n:number){const[y=0,m=1]=breakdownMonth.value.split('-').map(Number);const d=new Date(y,m-1+n,1);breakdownMonth.value=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;api(`/breakdown?month=${breakdownMonth.value}`).then(v=>breakdownData.value=v)}function shiftMonth(n:number){const[y=0,m=1]=month.value.split('-').map(Number);const d=new Date(y,m-1+n,1);month.value=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`}
</script>
<template>
<header class="page-head"><div><p class="eyebrow">MY MONEY GARDEN · {{monthLabel}}</p><h1>{{props.activeTab==='dashboard'?'오늘도 돈이 자라고 있어요':props.activeTab==='ledger'?'월별 가계부':props.activeTab==='saving'?'모아보기':'내 재테크 설정'}}</h1><p class="subtext">계획과 실제 기록을 나누어, 내 속도를 정확하게 확인해요.</p></div><button class="primary" @click="openEntry()">＋ 기록하기</button></header><p v-if="error" class="error">{{error}}</p><div v-if="loading" class="loading">재테콩을 준비하고 있어요…</div>
<template v-else-if="props.activeTab==='dashboard'"><section class="stats-grid"><article class="stat-card mint"><span>이번 달 사용 예산</span><div class="budget-label"><b>{{man(dashboard.expense)}}</b><b>/ {{man(dashboard.monthlyBudget)}}</b></div><div class="budget-bar"><i :style="{width:`${budgetPercent}%`}"></i></div></article><article class="stat-card peach"><span>이번 달 저축</span><strong>{{won(dashboard.saving)}}</strong><small>모은 금액 {{won(dashboard.totalSaving)}}</small></article><article class="stat-card lilac"><span>목표 달성률</span><strong>{{percent}}<em>%</em></strong><small>{{man(dashboard.goalAmount)}}</small></article></section><section class="card breakdown-card"><div class="section-title"><div><span class="eyebrow">THIS MONTH SPENDING</span><h2>이번 달 소비 비율</h2></div><span class="muted">{{won(breakdownTotal)}}</span></div><div class="breakdown-layout"><div class="pie-chart" :style="pieStyle"></div><div class="breakdown-list"><div v-for="(item,i) in breakdownData" :key="`${item.entry_type}-${item.category_name}-${item.detail_name}`"><i class="swatch" :style="{background:breakdownColor(item,Number(i))}"></i><span>{{breakdownLabel(item)}}</span><b>{{man(item.amount)}}</b></div><p v-if="!breakdownData?.length" class="empty">이번 달 소비 기록을 추가해보세요.</p></div></div></section></template>
<template v-else-if="props.activeTab==='ledger'"><section class="toolbar card"><div class="month-picker"><button @click="shiftMonth(-1)">‹</button><b>{{monthLabel}}</b><button @click="shiftMonth(1)">›</button></div><div class="toolbar-actions"><button class="soft-button" @click="modal='budget'">예산 {{man(budget.amount)}}</button><button class="soft-button" @click="openQuick()">간편기록</button><button class="primary" @click="openEntry()">＋ 기록하기</button></div></section><section class="ledger-layout"><div class="card calendar-card"><div class="calendar-week"><span v-for="d in ['월','화','수','목','금','토','일']" :key="d">{{d}}</span></div><div class="calendar-grid"><div v-for="cell in calendar" :key="cell.key||cell.date" class="calendar-day"><template v-if="!cell.blank"><b>{{cell.day}}</b><button class="day-add" @click="openEntry(cell.date)">＋</button><div v-for="e in cell.items" :key="e.id" class="calendar-money" :class="{'expense-day':e.entry_type==='EXPENSE','income-day':e.entry_type==='INCOME','saving-day':e.entry_type==='SAVING','debt-day':e.entry_type==='DEBT_REPAYMENT'}">{{e.entry_type==='INCOME'?'+':'-'}}{{Math.round(e.amount/10000)}}만</div></template></div></div></div><div class="card entry-list"><h2>거래 내역</h2><div v-for="e in entries" :key="e.id" class="list-row"><span class="record-dot" :class="{'income-record':e.entry_type==='INCOME','saving-record':e.entry_type==='SAVING','debt-record':e.entry_type==='DEBT_REPAYMENT','expense-record':e.entry_type==='EXPENSE'}">{{e.entry_type==='SAVING'?'🌱':e.entry_type==='DEBT_REPAYMENT'?'💳':e.emoji||'🧾'}}</span><div><b>{{e.detail_name||e.category_name}}</b><small>{{e.entry_date?.slice(5,10)}} · {{e.card_name||e.memo||''}}</small></div><strong>{{e.entry_type==='INCOME'?'+':e.entry_type==='SAVING'?'저축 ':e.entry_type==='DEBT_REPAYMENT'?'상환 ':'-'}}{{won(e.amount)}}</strong><span class="entry-actions"><button class="text-button" @click="editEntry(e)">수정</button><button class="text-button danger" @click="deleteEntry(e.id)">삭제</button></span></div><div v-if="!entries.length" class="empty">이 달의 기록이 없어요.</div></div></section></template>
<template v-else-if="props.activeTab==='saving'"><div class="subtabs"><button :class="{active:collectionTab==='saving'}" @click="collectionTab='saving'">저축</button><button :class="{active:collectionTab==='debt'}" @click="collectionTab='debt'">빚</button></div><template v-if="collectionTab==='saving'"><section class="saving-total card"><div><span class="eyebrow">TOTAL SAVINGS</span><h2>{{won(dashboard.totalSaving)}}</h2></div><button class="primary" @click="savingForm={name:'',type:'적금',rate:'0',maturityDate:'',amount:'0'};modal='saving'">＋ 저축상품 등록</button></section><section class="saving-grid"><article v-for="s in groupedSavings" :key="s.name" class="saving-card"><span class="saving-icon">🌱</span><span class="eyebrow">{{s.product_type}}</span><h3>{{s.name}}</h3><strong>{{won(s.current_amount)}}</strong><p>금리 {{s.interest_rate}}%</p><button class="text-button" @click="editSaving(s)">수정</button><button class="text-button danger" @click="deleteSaving(s.id)">삭제</button></article><article v-if="!groupedSavings.length" class="saving-card empty">아직 등록한 저축상품이 없어요.</article></section></template><template v-else><section class="card debt-section"><div class="section-title"><h2>빚 관리</h2><button class="soft-button" @click="debtForm={id:null,name:'',balance:'',rate:'0',dueDate:''};modal='debt'">＋ 빚 추가하기</button></div><div v-for="d in debts" :key="d.id" class="debt-row"><div><b>{{d.name}}</b><small>금리 {{d.interest_rate}}% · 누적 상환 {{won(d.paid_amount)}}</small></div><strong>남은 상환액 {{won(Number(d.balance)-Number(d.paid_amount||0))}}</strong><button class="text-button" @click="editDebt(d)">수정</button><button class="text-button danger" @click="deleteDebt(d.id)">삭제</button><button class="soft-button" @click="payment={debtId:d.id,amount:''};modal='payment'">월 상환액</button></div><div v-if="!debts.length" class="empty">등록된 빚이 없어요.</div></section></template></template>
<template v-else><div class="settings-tabs"><button v-for="tab in [['goal','목표'],['card','카드'],['category','카테고리'],['breakdown','소비 비율']]" :key="tab[0]" :class="{active:settingsTab===tab[0]}" @click="settingsTab=tab[0] as any">{{tab[1]}}</button></div><section class="settings-grid"><div v-if="settingsTab==='goal'" class="card setting-card"><span class="eyebrow">GOAL</span><h2>목표 설정</h2><p>{{goal.years}}년 동안 {{man(goal.amount)}} 모으기<br/>시작일 {{goal.startDate}}</p><button class="soft-button" @click="modal='goal'">목표 수정</button></div><div v-if="settingsTab==='card'" class="card setting-card card-setting"><span class="eyebrow">CARD</span><h2>내 카드</h2><p>등록된 카드 {{cards.length}}개 · 기본 카드 {{defaultCard?.name||'없음'}}</p><div class="card-list-preview"><div v-for="c in cards" :key="c.id" class="card-preview-row"><span>💳</span><div><b>{{c.name}}</b><small>{{c.card_type}}</small></div><strong v-if="c.is_default">기본 카드</strong></div><p v-if="!cards.length" class="empty">등록된 카드가 없어요.</p></div><button class="soft-button" @click="modal='card'">카드 관리</button></div><div v-if="settingsTab==='category'" class="card setting-card category-setting"><span class="eyebrow">CATEGORY</span><h2>카테고리</h2><p>{{categories.length}}개의 카테고리와 세부항목</p><button class="soft-button" @click="category={id:null,name:'',type:'EXPENSE',detail:'',emoji:'🌱',color:'#7DBA8B'};modal='category'">＋ 카테고리 추가</button><div class="category-list"><div v-for="c in categories" :key="c.id" class="category-item"><span>{{c.emoji}} {{c.name}}<small>{{c.detail_name}}</small></span><span><button class="text-button" @click="editCategory(c)">수정</button><button class="text-button danger" @click="deleteCategory(c.id)">삭제</button></span></div></div></div><div v-if="settingsTab==='breakdown'" class="card setting-card breakdown-setting"><span class="eyebrow">MONTHLY BREAKDOWN</span><div class="breakdown-month-head"><button class="soft-button" @click="shiftBreakdown(-1)">‹</button><h2>{{breakdownMonth}} 소비 비율</h2><button class="soft-button" @click="shiftBreakdown(1)">›</button></div><p>소득을 제외한 소비·저축·빚 상환 내역이에요.</p><div class="breakdown-layout"><div class="pie-chart" :style="pieStyle"></div><div class="breakdown-list"><div v-for="(item,i) in breakdownData" :key="`setting-${item.entry_type}-${item.detail_name}`"><i class="swatch" :style="{background:breakdownColor(item,Number(i))}"></i><span>{{breakdownLabel(item)}}</span><b>{{won(item.amount)}}</b></div><p v-if="!breakdownData?.length" class="empty">이번 달 기록이 없어요.</p></div></div></div></section></template>
<div v-if="modal" class="modal-backdrop" @click.self="modal=''">
<form v-if="modal==='goal'" class="modal" @submit.prevent="saveGoal"><button type="button" class="close" @click="modal=''">×</button><span class="eyebrow">GOAL</span><h2>목표 설정</h2><label>목표 금액<input v-model="goal.amount" type="number" required/><small class="number-hint">{{man(goal.amount)}}</small></label><label>몇 년 동안 모을까요?<input v-model="goal.years" type="number" min="1" required/></label><label>시작일<input v-model="goal.startDate" type="date" required/></label><button class="primary full">목표 저장</button></form>
<form v-else-if="modal==='budget'" class="modal" @submit.prevent="saveBudget"><button type="button" class="close" @click="modal=''">×</button><span class="eyebrow">MONTHLY BUDGET · {{monthLabel}}</span><h2>이번 달 예산</h2><label>사용 예산<input v-model="budget.amount" type="number" required/><small class="number-hint">{{man(budget.amount)}}</small></label><label class="check-line"><input v-model="budget.copyNext" type="checkbox"/> 다음달에도 동일한 예산을 설정하겠습니까?</label><button class="primary full">예산 저장</button></form>
<form v-else-if="modal==='entry'" class="modal" @submit.prevent="saveEntry"><button type="button" class="close" @click="modal=''">×</button><span class="eyebrow">NEW RECORD · {{entry.date}}</span><h2>소비·소득 기록</h2><label>구분<select v-model="entry.type"><option value="EXPENSE">소비</option><option value="INCOME">소득</option><option value="SAVING">저축</option><option value="DEBT_REPAYMENT">빚 상환</option></select></label><label>날짜<input v-model="entry.date" type="date" required/></label><label v-if="entry.type!=='SAVING'&&entry.type!=='DEBT_REPAYMENT'">대분류<select v-model="entry.categoryGroup" @change="entry.categoryId=''" required><option value="">대분류 선택</option><option v-for="g in entryGroups" :key="g">{{g}}</option></select><span class="field-label">소분류</span><select v-model="entry.categoryId" required><option value="">소분류 선택</option><option v-for="c in entryDetails" :key="c.id" :value="c.id">{{c.emoji}} {{c.detail_name||c.name}}</option></select></label><label v-else-if="entry.type==='SAVING'">저축 상품<select v-model="entry.savingsProductId" required><option value="">저축상품 선택</option><option v-for="s in savings" :key="s.id" :value="s.id">🌱 {{s.name}}</option></select></label><label v-else>상환할 빚<select v-model="entry.debtId" required><option value="">빚 선택</option><option v-for="d in debts" :key="d.id" :value="d.id">{{d.name}} · 남은 {{won(Number(d.balance)-Number(d.paid_amount||0))}}</option></select></label><label v-if="entry.type==='EXPENSE'||entry.type==='INCOME'">카드<select v-model="entry.cardId"><option v-for="c in cards" :key="c.id" :value="c.id">{{c.name}} ({{c.card_type}})</option></select></label><p v-if="(entry.type==='EXPENSE'||entry.type==='INCOME')&&defaultCard" class="modal-note">기본 카드인 {{defaultCard.name}} ({{defaultCard.card_type}})로 기록됩니다.</p><label>금액<input v-model="entry.amount" type="number" required/><small class="number-hint">{{man(entry.amount)}}</small></label><label>메모<input v-model="entry.memo"/></label><button class="primary full">기록 저장</button></form>
<form v-else-if="modal==='quick'" class="modal" @submit.prevent="saveQuick"><button type="button" class="close" @click="modal=''">×</button><span class="eyebrow">QUICK RECORD</span><h2>간편기록</h2><label>날짜<input v-model="entry.date" type="date" required/></label><p class="modal-note">기본 카드인 {{defaultCard?.name||'기본 카드'}}로 기록됩니다.</p><div v-for="(r,i) in quickRows" :key="i" class="quick-row"><input v-model="r.amount" type="number" placeholder="금액"/><select v-model="r.categoryGroup" @change="r.categoryId=''" required><option value="">대분류</option><option v-for="g in quickGroups" :key="g">{{g}}</option></select><select v-model="r.categoryId" required><option value="">소분류</option><option v-for="c in quickDetails(r)" :key="c.id" :value="c.id">{{c.emoji}} {{c.detail_name||c.name}}</option></select><button type="button" class="remove-row" @click="quickRows.splice(i,1)">×</button></div><button type="button" class="soft-button full" @click="quickRows.push({amount:'',categoryGroup:'',categoryId:''})">＋ 항목 추가</button><button class="primary full">간편기록 저장</button></form>
<form v-else-if="modal==='saving'" class="modal" @submit.prevent="saveSaving"><button type="button" class="close" @click="modal=''">×</button><span class="eyebrow">SAVING</span><h2>{{savingForm.id?'저축상품 수정':'저축상품 추가'}}</h2><label>상품명<input v-model="savingForm.name" required/></label><label>종류<select v-model="savingForm.type"><option>적금</option><option>예금</option><option>파킹통장</option><option>ETF</option></select></label><label>금리(%)<input v-model="savingForm.rate" type="number" step="0.01"/></label><label>현재 잔액<input v-model="savingForm.amount" type="number"/><small class="number-hint">{{man(savingForm.amount)}}</small></label><label>만기일<input v-model="savingForm.maturityDate" type="date"/></label><button class="primary full">저장</button></form>
<form v-else-if="modal==='debt'" class="modal" @submit.prevent="saveDebt"><button type="button" class="close" @click="modal=''">×</button><span class="eyebrow">DEBT</span><h2>{{debtForm.id?'빚 수정':'빚 추가하기'}}</h2><label>이름<input v-model="debtForm.name" required/></label><label>남은 금액<input v-model="debtForm.balance" type="number" required/><small class="number-hint">{{man(debtForm.balance)}}</small></label><label>금리(%)<input v-model="debtForm.rate" type="number" step="0.01"/></label><label>상환 예정일<input v-model="debtForm.dueDate" type="date"/></label><button class="primary full">저장</button></form>
<form v-else-if="modal==='payment'" class="modal" @submit.prevent="savePayment"><button type="button" class="close" @click="modal=''">×</button><span class="eyebrow">DEBT PAYMENT · {{monthLabel}}</span><h2>월 상환액</h2><label>상환 금액<input v-model="payment.amount" type="number" required/><small class="number-hint">{{man(payment.amount)}}</small></label><button class="primary full">상환액 저장</button></form>
<form v-else-if="modal==='card'" class="modal" @submit.prevent="addCard"><button type="button" class="close" @click="modal=''">×</button><span class="eyebrow">CARD</span><h2>내 카드 관리</h2><div v-for="c in cards" :key="c.id" class="list-row"><div><b>{{c.name}}</b><small>{{c.card_type}}</small></div><button type="button" class="text-button" @click="setDefault(c.id)">{{c.is_default?'기본 카드':'기본으로 설정'}}</button></div><label>카드 이름<input v-model="card.name" required/></label><label>종류<select v-model="card.type"><option>체크카드</option><option>신용카드</option></select></label><label class="check-line"><input v-model="card.isDefault" type="checkbox"/> 기본 카드로 설정</label><button class="primary full">카드 추가</button></form>
<form v-else class="modal" @submit.prevent="saveCategory"><button type="button" class="close" @click="modal=''">×</button><span class="eyebrow">CATEGORY</span><h2>{{category.id?'카테고리 수정':'세부항목 추가'}}</h2><label>상위 카테고리<input v-model="category.name" required/></label><label>구분<select v-model="category.type"><option value="EXPENSE">소비</option><option value="INCOME">소득</option><option value="SAVING">저축</option></select></label><label>세부항목<input v-model="category.detail" required/></label><label>이모지<input v-model="category.emoji" maxlength="2"/></label><button class="primary full">카테고리 저장</button></form></div>
</template>
